CREATE TABLE "public"."notification_events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."notification_events_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "event_type" text NOT NULL,
  "entity_type" text NOT NULL,
  "entity_id" text NOT NULL,
  "employee_sys_id" bigint,
  "project_id" bigint,
  "actor_user_id" uuid,
  "event_key" text NOT NULL,
  "event_payload" jsonb DEFAULT '{}'::jsonb NOT NULL,
  "occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
  "processing_status" text DEFAULT 'Pending'::text NOT NULL,
  "processed_at" timestamp with time zone,
  "processing_error" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."notification_events" OWNER TO "postgres";
COMMENT ON TABLE "public"."notification_events" IS 'Normalized and idempotent HRM business-event ledger used as the source for notification generation.';
COMMENT ON COLUMN "public"."notification_events"."event_key" IS 'Stable unique business-event key used to prevent duplicate event creation.';
COMMENT ON COLUMN "public"."notification_events"."event_payload" IS 'Structured event context. Secrets and unnecessary sensitive information must not be stored here.';
